// src/main.rs
use std::env;
use std::time::Duration;

use reqwest::StatusCode;
use serde::Deserialize;
use serde_json::Value;

#[derive(Deserialize)]
struct IamTokenResponse {
    access_token: String,
    token_type: String,
    expires_in: i64,
    expiration: i64,
    refresh_token: Option<String>,
}

async fn fetch_iam_token(client: &reqwest::Client, api_key: &str) -> Result<String, String> {
    let url = "";
    let body = format!("grant_type=urn:ibm:params:oauth:grant-type:apikey&apikey={}", urlencoding::Encoded::new(api_key));
    let mut last_err = String::new();
    for _ in 0..3 {
        let res = client
            .post(url)
            .header("accept", "application/json")
            .header("content-type", "application/x-www-form-urlencoded")
            .body(body.clone())
            .timeout(Duration::from_secs(20))
            .send()
            .await;
        match res {
            Ok(r) => {
                if r.status().is_success() {
                    let v: IamTokenResponse = r.json().await.map_err(|e| e.to_string())?;
                    if v.access_token.is_empty() {
                        return Err("empty access_token".to_string());
                    }
                    return Ok(v.access_token);
                } else if r.status().is_server_error() || r.status() == StatusCode::TOO_MANY_REQUESTS {
                    last_err = format!("server error {}", r.status());
                } else {
                    let code = r.status();
                    let txt = r.text().await.unwrap_or_default();
                    return Err(format!("iam error {} {}", code, txt));
                }
            }
            Err(e) => {
                last_err = e.to_string();
            }
        }
        tokio::time::sleep(Duration::from_millis(400)).await;
    }
    Err(last_err)
}

async fn fetch_backends(client: &reqwest::Client, bearer: &str, service_crn: &str) -> Result<Value, String> {
    let url = "";
    let mut last_err = String::new();
    for _ in 0..3 {
        let res = client
            .get(url)
            .header("accept", "application/json")
            .header("authorization", format!("Bearer {}", bearer))
            .header("Service-CRN", service_crn)
            .header("IBM-API-Version", "2025-05-01")
            .timeout(Duration::from_secs(20))
            .send()
            .await;
        match res {
            Ok(r) => {
                if r.status().is_success() {
                    let v: Value = r.json().await.map_err(|e| e.to_string())?;
                    return Ok(v);
                } else if r.status().is_server_error() || r.status() == StatusCode::TOO_MANY_REQUESTS {
                    last_err = format!("backend server error {}", r.status());
                } else {
                    let code = r.status();
                    let txt = r.text().await.unwrap_or_default();
                    return Err(format!("backend error {} {}", code, txt));
                }
            }
            Err(e) => {
                last_err = e.to_string();
            }
        }
        tokio::time::sleep(Duration::from_millis(400)).await;
    }
    Err(last_err)
}

#[tokio::main(flavor = "multi_thread")]
async fn main() {
    let api_key = env::var("IBM_API_KEY").unwrap_or_default();
    let service_crn = env::var("IBM_INSTANCE_CRN").unwrap_or_default();
    if api_key.is_empty() || service_crn.is_empty() {
        eprintln!("missing IBM_API_KEY or IBM_INSTANCE_CRN");
        std::process::exit(2);
    }
    let client = reqwest::Client::builder()
        .user_agent("ibm-quantum-client/0.1")
        .pool_max_idle_per_host(2)
        .http2_adaptive_window(true)
        .tcp_keepalive(Duration::from_secs(30))
        .timeout(Duration::from_secs(30))
        .build()
        .expect("client");
    let token = match fetch_iam_token(&client, &api_key).await {
        Ok(t) => t,
        Err(e) => {
            eprintln!("{}", e);
            std::process::exit(3);
        }
    };
    let backends = match fetch_backends(&client, &token, &service_crn).await {
        Ok(v) => v,
        Err(e) => {
            eprintln!("{}", e);
            std::process::exit(4);
        }
    };
    println!("{}", serde_json::to_string_pretty(&backends).unwrap());
}
