/* main.c */
#include <stdio.h>
#include <stdlib.h>
#include "dotprod.h"

static void die(const char* msg) {
    fprintf(stderr, "%s\n", msg);
    exit(1);
}

int main(int argc, char** argv) {
    struct futhark_context_config* cfg = futhark_context_config_new();
    if (!cfg) die("cfg");
    struct futhark_context* ctx = futhark_context_new(cfg);
    if (!ctx) die("ctx");
    int32_t xdata[4] = {1,2,3,4};
    int32_t ydata[4] = {2,3,4,1};
    struct futhark_i32_1d* x = futhark_new_i32_1d(ctx, xdata, 4);
    if (!x) die("x");
    struct futhark_i32_1d* y = futhark_new_i32_1d(ctx, ydata, 4);
    if (!y) die("y");
    int32_t res = 0;
    if (futhark_entry_dotprod(ctx, &res, x, y) != 0) die("entry");
    if (futhark_context_sync(ctx) != 0) die("sync");
    printf("%d\n", res);
    if (futhark_free_i32_1d(ctx, x) != 0) die("freex");
    if (futhark_free_i32_1d(ctx, y) != 0) die("freey");
    futhark_context_free(ctx);
    futhark_context_config_free(cfg);
    return 0;
}
