const std = @import("std");
const mem = std.mem;
const net = std.net;
const http = std.http;

pub const QuantumClientError = error{
    IamTokenError,
    BackendListError,
    MissingEnvironmentVariable,
    NetworkError,
    ParseError,
    TlsError,
    OutOfMemory,
};

pub const IamTokenResponse = struct {
    access_token: []const u8,
    token_type: []const u8,
    expires_in: i64,
    expiration: i64,
    refresh_token: ?[]const u8,
};

pub fn fetchIamToken(allocator: mem.Allocator, api_key: []const u8) ![]u8 {
    const iam_url = "";
    const iam_path = "/identity/token";

    var client = http.Client{ .allocator = allocator };
    defer client.deinit();

    const body_str = try std.fmt.allocPrint(allocator, "grant_type=urn:ibm:params:oauth:grant-type:apikey&apikey={s}", .{api_key});
    defer allocator.free(body_str);

    var header_buffer: [4096]u8 = undefined;
    var req = try client.open(.POST, try std.Uri.parse(iam_url ++ iam_path), .{
        .server_header_buffer = &header_buffer,
        .extra_headers = &.{
            .{ .name = "accept", .value = "application/json" },
            .{ .name = "content-type", .value = "application/x-www-form-urlencoded" },
        },
    });
    defer req.deinit();

    req.transfer_encoding = .{ .content_length = body_str.len };
    try req.send();
    try req.writeAll(body_str);
    try req.finish();
    try req.wait();

    if (req.response.status != .ok) {
        return QuantumClientError.IamTokenError;
    }

    var response_buffer = std.ArrayList(u8).init(allocator);
    defer response_buffer.deinit();

    const response_body = try req.reader().readAllArrayList(&response_buffer, 1024 * 1024);
    _ = response_body;

    const parsed = try std.json.parseFromSlice(IamTokenResponse, allocator, response_buffer.items, .{});
    defer parsed.deinit();

    return allocator.dupe(u8, parsed.value.access_token);
}

pub fn fetchBackends(allocator: mem.Allocator, bearer_token: []const u8, service_crn: []const u8) !std.json.Parsed(std.json.Value) {
    const backend_url = "";
    const backend_path = "/api/v1/backends";

    var client = http.Client{ .allocator = allocator };
    defer client.deinit();

    const auth_header = try std.fmt.allocPrint(allocator, "Bearer {s}", .{bearer_token});
    defer allocator.free(auth_header);

    var header_buffer: [8192]u8 = undefined;
    var req = try client.open(.GET, try std.Uri.parse(backend_url ++ backend_path), .{
        .server_header_buffer = &header_buffer,
        .extra_headers = &.{
            .{ .name = "accept", .value = "application/json" },
            .{ .name = "authorization", .value = auth_header },
            .{ .name = "Service-CRN", .value = service_crn },
            .{ .name = "IBM-API-Version", .value = "2025-05-01" },
        },
    });
    defer req.deinit();

    try req.send();
    try req.finish();
    try req.wait();

    if (req.response.status != .ok) {
        return QuantumClientError.BackendListError;
    }

    var response_buffer = std.ArrayList(u8).init(allocator);
    defer response_buffer.deinit();

    const response_body = try req.reader().readAllArrayList(&response_buffer, 10 * 1024 * 1024);
    _ = response_body;

    const parsed = try std.json.parseFromSlice(std.json.Value, allocator, response_buffer.items, .{});
    return parsed;
}

pub fn getQuantumBackends(allocator: mem.Allocator) !std.json.Parsed(std.json.Value) {
    const api_key = std.process.getEnvVarOwned(allocator, "IBM_API_KEY") catch return QuantumClientError.MissingEnvironmentVariable;
    defer allocator.free(api_key);

    const service_crn = std.process.getEnvVarOwned(allocator, "IBM_INSTANCE_CRN") catch return QuantumClientError.MissingEnvironmentVariable;
    defer allocator.free(service_crn);

    const bearer_token = try fetchIamToken(allocator, api_key);
    defer allocator.free(bearer_token);

    return fetchBackends(allocator, bearer_token, service_crn);
}
