```futhark
entry batched_matmul [k][m][n] (a: [k][m][n]f32) (b: [k][n][m]f32): [k][m][m]f32 =
  map2 (\a_mat b_mat ->
    map (\a_row ->
      map (\b_col ->
        f32.sum (map2 (*) a_row b_col)
      ) (transpose b_mat)
    ) a_mat
  ) a b
